def cycle_basis(G):
    # Paton cycle basis
    gnodes=set(G); cycles=[]
    while gnodes:
        root=gnodes.pop(); stack=[root]; pred={root:root}; used={root:set()}
        while stack:
            z=stack.pop(); zused=used[z]
            for nbr in G[z]:
                if nbr not in used:
                    pred[nbr]=z; stack.append(nbr); used[nbr]={z}
                elif nbr==z:
                    cycles.append([z])
                elif nbr not in zused:
                    pn=used[nbr]; cycle=[nbr,z]; p=pred[z]
                    while p not in pn:
                        cycle.append(p); p=pred[p]
                    cycle.append(p); cycles.append(cycle)
                    used[nbr].add(z)
        gnodes-=set(pred)
    return cycles

