from collections import deque

def minimum_cycle_basis(G):
    candidates=[]
    for u in G:
        for v in G[u]:
            if u>=v: continue
            # shortest paths from every root to u and v with edge omitted
            for root in G:
                paths={root:[root]}; q=deque([root])
                while q:
                    x=q.popleft()
                    for y in G[x]:
                        if (x==u and y==v) or (x==v and y==u): continue
                        if y not in paths:
                            paths[y]=paths[x]+[y]; q.append(y)
                if u in paths and v in paths:
                    pu=paths[u]; pv=paths[v]
                    common=set(pu)&set(pv)
                    # root should be last common along paths; trim to last common
                    last=next(x for x in reversed(pu) if x in common)
                    pu=pu[pu.index(last):]; pv=pv[pv.index(last):]
                    cyc=pu+list(reversed(pv[:-1]))
                    candidates.append(cyc)
    candidates.sort(key=len)
    basis=[]; basis_sets=[]
    for cyc in candidates:
        s=set(cyc)
        if len(s)<3: continue
        # vertices suffice for simple cycle independence here? use edges
        es={tuple(sorted((cyc[i],cyc[(i+1)%len(cyc)]))) for i in range(len(cyc))}
        reduced=set(es)
        for bs in basis_sets:
            # symmetric diff always; independence testing this greedy works if sequential reductions
            reduced ^= bs
        if reduced:
            basis.append(cyc); basis_sets.append(es)
    return basis

